 'use strict';
(()=>{
 const D=window.GameData,K=window.CharacterData;
 const artKeys=['guard','bash','taunt','serin_dash','serin_cut','serin_parry','serin_dance','shot','volley','heal','wave','serin_chain','serin_cover','boss_rescue','boss_retreat'];
 const symbols={escort:'◆',pursuit:'↗',resonance:'✦'};
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function color(key){return window.CardTraits.traits[D.cards[key].traits[0]].color;}
 function art(key){if(['serin_dance','serin_ultimate'].includes(key))return `<img class="card-illustration" src="assets/serin-dance-v2.png" alt="${esc(D.cards[key].name)} · 세린의 검무" loading="lazy" decoding="async">`;const authored=window.ContentAuthoring?.art[key];if(authored)return `<img class="card-illustration" src="${esc(authored)}" alt="${esc(D.cards[key].name)} 기술 그림">`;if(key.startsWith('ria_'))return `<svg class="card-illustration" viewBox="0 0 200 200" role="img" aria-label="${esc(D.cards[key].name)} 기술 그림"><rect width="200" height="200" fill="#292d49"/><circle cx="110" cy="91" r="58" fill="none" stroke="${color(key)}" stroke-width="3"/><path d="M110 20V162M40 91H181" stroke="#aaa3f2" stroke-width="2"/>${key==='ria_cover'?'<path d="M83 53L138 53L145 98Q115 153 76 98Z" fill="#9dded155" stroke="#9dded1" stroke-width="4"/>':`<path d="M20 166L143 62${key==='ria_burst'?'M36 178L160 73M6 152L128 47':''}" fill="none" stroke="#eee8ff" stroke-width="5"/>`}</svg>`;if(D.cards[key].spatial){const heal=D.cards[key].spatial==='circleHeal';return `<svg class="card-illustration spatial-card-art" viewBox="0 0 200 200" role="img" aria-label="${esc(D.cards[key].name)} 공간 효과 그림"><rect width="200" height="200" fill="#172e3c"/>${heal?'<circle cx="100" cy="100" r="68" fill="#8ad4a433" stroke="#b6eac8" stroke-width="3"/><path d="M100 70V130M70 100H130" stroke="#c9f4d5" stroke-width="7"/><circle cx="52" cy="95" r="10" fill="#b6eac8"/><circle cx="138" cy="134" r="10" fill="#b6eac8"/><circle cx="182" cy="30" r="10" fill="#62717a"/>':'<path d="M25 163L151 27L174 49L47 184Z" fill="#e8bc7b44" stroke="#f2d8a6" stroke-width="2"/><path d="M35 174L162 37" stroke="#fff0bb" stroke-width="5"/><circle cx="80" cy="125" r="12" fill="#d08e80"/><circle cx="132" cy="69" r="12" fill="#d08e80"/><circle cx="158" cy="147" r="12" fill="#62717a"/>'}</svg>`;}const index=artKeys.indexOf(key),i=index<0?15:index;return `<div class="card-illustration" role="img" aria-label="${esc(D.cards[key].name)} 기술 그림" style="--art-x:${(i%4)*100/3}%;--art-y:${Math.floor(i/4)*100/3}%"></div>`;}
 function trait(id,label=null){const t=window.CardTraits.traits[id];return `<span class="trait-badge" data-trait="${id}" style="--trait-color:${t.color}" title="${esc(t.desc)}"><span aria-hidden="true">${symbols[id]||'◇'}</span> ${esc(label||t.name)}</span>`;}
 function badges(key){return D.cards[key].traits.map(id=>trait(id)).join('');}
 const states={selected:'선택됨',comparing:'비교 중',equipped:'편성됨',reserve:'대기',evolved:'진화',normal:'일반'};
 function features(card){if(typeof card==='string')card={key:card};const d=D.definition(card),out=[];if(d.movement)return ['이동'];if(['attack','area','execute','pierce','mark','slow'].includes(d.kind))out.push('공격');if(['heal','healAll','cleanse','blessing'].includes(d.kind)&&d.power)out.push('회복');if(['guard','ward','armor','taunt'].includes(d.kind))out.push('보호');if(['buff','blessing','mark','slow','taunt','cleanse'].includes(d.kind))out.push('지원');if(d.dash||d.approach||['retreatStrike','coverWard'].includes(K.skill(card.key).type))out.push('이동');return out.length?out:['지원'];}
 function state(id,text=null){return states[id]?`<span class="card-state" data-state="${id}">${esc(text||states[id])}</span>`:'';}
 function identity(card,options={}){if(typeof card==='string')card={key:card};const d=D.definition(card),owner=K.owner(card.key),caster=options.caster||(options.party?K.character(card.casterSlot!==undefined?options.party[card.casterSlot]?.characterId:options.party.find(p=>K.canCast(card,K.character(p.characterId)))?.characterId):null),name=caster?.name||owner?.name||D.roles[d.role].name;return `<div class="card-identity" data-card-key="${card.key}"><small class="card-owner"><span class="owner-symbol" aria-hidden="true">${['♜','✦','➶','✚'][d.role]}</span>${esc(name)}</small>${options.hideName?'':`<strong class="identity-name">${esc(d.name)}</strong>`}<div class="card-tags">${badges(card.key)}<span class="card-function">${features(card).join(' · ')}</span></div><div class="card-states">${options.state?state(options.state):''}${card.upgraded?state('evolved'):''}</div></div>`;}
 function metrics(card,definition=null){const d=definition||D.definition(card),number=n=>Number(n.toFixed(2)),items=[];
 if(d.power&&['armor','buff'].includes(d.kind))items.push(`${d.kind==='armor'?'받는 피해 감소':'피해 증가'} ${number(d.power*100)}%`);else if(d.power){const label=d.kind==='ward'?'보호막': ['heal','healAll','cleanse','blessing'].includes(d.kind)?'회복':d.kind==='area'?'적마다 피해':'기본 피해';items.push(`${label} ${number(d.power)}${K.skill(card.key).type==='comboStrike'?' × '+(1+K.skill(card.key).offsets.length)+'타':''}`);}
 if(d.duration)items.push(`지속 ${number(d.duration)}초`);
 if(d.prep)items.push(`준비 ${number(d.prep)}초`);
 if(d.spatial==='circleHeal')items.push(`시전자 주변 · 반경 ${d.radius}`);if(d.spatial==='line')items.push(`방향 고정 · 길이 ${d.length} / 폭 ${d.width}`);
 items.push(`다음 명령 ${d.time}초`);return items;
 }
 function body(card,options={}){if(typeof card==='string')card={key:card};const d=D.definition(card);return `${art(card.key)}<div class="card-copy">${identity(card,options)}<small class="card-source">${d.source==='reward'?'원정 보상':card.acquired?'원정 획득 · 기초 카드':'기초 카드'}</small><p class="card-description">${esc(d.desc)}</p><div class="card-metrics">${metrics(card).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${card.upgraded?'<small class="card-evolution-note">진화 수치 적용 · 특성은 원본과 동일</small>':''}</div>`;}
 window.CardVisuals={artKeys,art,badges,body,color,metrics,identity,features,state,states,trait};
})();
